#!/usr/bin/env node
/** Focused diagnostic: what happens when “Auswählen” is clicked inside the
 *  full-screen comparison view? Does the detail panel become visible? */
import { spawn } from 'node:child_process';
import os from 'node:os';
import path from 'node:path';

const PORT = 9333;
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

class CDP {
  constructor(ws) {
    this.ws = ws;
    this.id = 0;
    this.pending = new Map();
    this.handlers = new Map();
    ws.addEventListener('message', (event) => {
      const msg = JSON.parse(event.data);
      if (msg.id && this.pending.has(msg.id)) {
        const { resolve, reject } = this.pending.get(msg.id);
        this.pending.delete(msg.id);
        msg.error ? reject(new Error(msg.error.message)) : resolve(msg.result);
      } else if (msg.method) {
        for (const fn of this.handlers.get(msg.method) ?? []) fn(msg.params);
      }
    });
  }
  on(method, fn) {
    if (!this.handlers.has(method)) this.handlers.set(method, []);
    this.handlers.get(method).push(fn);
  }
  send(method, params = {}) {
    const id = ++this.id;
    return new Promise((resolve, reject) => {
      this.pending.set(id, { resolve, reject });
      this.ws.send(JSON.stringify({ id, method, params }));
    });
  }
  async eval(expression) {
    const r = await this.send('Runtime.evaluate', { expression, returnByValue: true, awaitPromise: true });
    if (r.exceptionDetails) throw new Error(r.exceptionDetails.exception?.description || 'eval failed');
    return r.result.value;
  }
  async click(selector) {
    const box = await this.eval(`(() => { const n = document.querySelector(${JSON.stringify(selector)}); if (!n) return null; const b = n.getBoundingClientRect(); return { x: b.x + b.width / 2, y: b.y + b.height / 2 }; })()`);
    if (!box) throw new Error(`no element ${selector}`);
    const common = { x: Math.round(box.x), y: Math.round(box.y), button: 'left', clickCount: 1 };
    await this.send('Input.dispatchMouseEvent', { type: 'mouseMoved', ...common });
    await this.send('Input.dispatchMouseEvent', { type: 'mousePressed', ...common });
    await this.send('Input.dispatchMouseEvent', { type: 'mouseReleased', ...common });
  }
}

const chrome = spawn('chromium', ['--headless=new', '--no-sandbox', '--disable-gpu', '--disable-dev-shm-usage', '--hide-scrollbars', '--window-size=1440,960', `--remote-debugging-port=${PORT}`, `--user-data-dir=${path.join(os.tmpdir(), 'probe-compare-' + process.pid)}`, 'about:blank'], { stdio: ['ignore', 'ignore', 'pipe'] });
let target;
for (let i = 0; i < 100 && !target; i++) {
  await sleep(300);
  try {
    const res = await fetch(`http://127.0.0.1:${PORT}/json/new?about:blank`, { method: 'PUT' });
    if (res.ok) target = (await res.json()).webSocketDebuggerUrl;
  } catch { /* not up */ }
}
if (!target) { chrome.kill(); throw new Error('no devtools'); }
const ws = new WebSocket(target);
await new Promise((resolve, reject) => { ws.addEventListener('open', resolve, { once: true }); ws.addEventListener('error', reject, { once: true }); });
const cdp = new CDP(ws);
await cdp.send('Page.enable');
await cdp.send('Runtime.enable');
const loaded = new Promise((r) => cdp.on('Page.loadEventFired', r));
await cdp.send('Page.navigate', { url: 'http://127.0.0.1:8787/?cmp=e-rara:7203621,e-rara:6698004' });
await loaded;
await sleep(4000);

console.log('compare button visible:', await cdp.eval(`(() => { const b = document.querySelector('#compare-open'); return b ? { hidden: b.hidden, text: b.textContent.trim() } : null; })()`));
await cdp.click('#compare-open');
await sleep(800);
console.log('compare view open:', await cdp.eval(`(() => ({ open: !document.querySelector('#compare-view').hidden, panes: document.querySelectorAll('.app-compare__pane').length }))()`));
await cdp.click('.app-compare__pane .app-compare__paneactions button');
await sleep(1200);
console.log(await cdp.eval(`(() => {
  const detail = document.querySelector('#detail');
  const view = document.querySelector('#compare-view');
  const btn = detail?.querySelector('.app-detail__close, button');
  const r = detail.getBoundingClientRect();
  const cx = Math.min(Math.max(Math.round(r.x + r.width / 2), 0), 1439);
  const cy = Math.min(Math.max(Math.round(r.y + 30), 0), 959);
  const top = document.elementFromPoint(cx, cy);
  return {
    detailHidden: detail.hidden,
    detailRect: { x: Math.round(r.x), y: Math.round(r.y), w: Math.round(r.width), h: Math.round(r.height) },
    compareHidden: view.hidden,
    topElement: top ? top.tagName + '.' + String(top.className).split(' ').slice(0, 3).join('.') : null,
    selected: new URL(location.href).searchParams.get('sel'),
    status: document.querySelector('#compare-status')?.textContent?.trim(),
  };
})()`));
chrome.kill();

