#!/usr/bin/env node
/** Layout measurement: map top/visible per viewport after the control-size change. */
import { spawn } from 'node:child_process';
import os from 'node:os';
import path from 'node:path';
const PORT = 9334;
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
class CDP {
  constructor(ws) {
    this.ws = ws; this.id = 0; this.pending = new Map(); this.handlers = new Map();
    ws.addEventListener('message', (e) => {
      const m = JSON.parse(e.data);
      if (m.id && this.pending.has(m.id)) { const p = this.pending.get(m.id); this.pending.delete(m.id); m.error ? p.reject(new Error(m.error.message)) : p.resolve(m.result); }
      else if (m.method) for (const fn of this.handlers.get(m.method) ?? []) fn(m.params);
    });
  }
  on(m, fn) { if (!this.handlers.has(m)) this.handlers.set(m, []); this.handlers.get(m).push(fn); }
  send(method, params = {}) { const id = ++this.id; return new Promise((res, rej) => { this.pending.set(id, { resolve: res, reject: rej }); this.ws.send(JSON.stringify({ id, method, params })); }); }
  async eval(expression) { const r = await this.send('Runtime.evaluate', { expression, returnByValue: true, awaitPromise: true }); if (r.exceptionDetails) throw new Error(r.exceptionDetails.exception?.description); return r.result.value; }
}
const chrome = spawn('chromium', ['--headless=new', '--no-sandbox', '--disable-gpu', '--disable-dev-shm-usage', '--hide-scrollbars', `--remote-debugging-port=${PORT}`, `--user-data-dir=${path.join(os.tmpdir(), 'measure-' + process.pid)}`, 'about:blank'], { stdio: ['ignore', 'ignore', 'pipe'] });
let target;
for (let i = 0; i < 100 && !target; i++) { await sleep(300); try { const r = await fetch(`http://127.0.0.1:${PORT}/json/new?about:blank`, { method: 'PUT' }); if (r.ok) target = (await r.json()).webSocketDebuggerUrl; } catch {} }
const ws = new WebSocket(target);
await new Promise((res, rej) => { ws.addEventListener('open', res, { once: true }); ws.addEventListener('error', rej, { once: true }); });
const cdp = new CDP(ws);
await cdp.send('Page.enable'); await cdp.send('Runtime.enable');
const viewports = [[1440, 900], [1280, 900], [1024, 900], [840, 900], [600, 900], [390, 844], [320, 640]];
for (const [w, h] of viewports) {
  await cdp.send('Emulation.setDeviceMetricsOverride', { width: w, height: h, deviceScaleFactor: 1, mobile: w < 600 });
  const loaded = new Promise((r) => cdp.on('Page.loadEventFired', r));
  await cdp.send('Page.navigate', { url: 'http://127.0.0.1:8787/' });
  await loaded;
  await cdp.eval(`new Promise((r) => { const t = setInterval(() => { if (document.querySelector('#map') && document.querySelectorAll('#result-list > *').length > 0) { clearInterval(t); r(true); } }, 200); setTimeout(() => { clearInterval(t); r(false); }, 15000); })`);
  await sleep(1200);
  const m = await cdp.eval(`(() => {
    const map = document.querySelector('#map')?.getBoundingClientRect();
    const header = document.querySelector('.zh-header')?.getBoundingClientRect();
    const button = document.querySelector('#place-submit')?.getBoundingClientRect();
    const input = document.querySelector('#place-input')?.getBoundingClientRect();
    const toolbar = document.querySelector('.app-toolbar')?.getBoundingClientRect();
    return {
      mapTop: Math.round(map?.top ?? -1),
      mapVisible: Math.round(Math.min(window.innerHeight - map.top, map.height)),
      header: Math.round(header?.height ?? -1),
      searchBtn: Math.round(button?.height ?? -1),
      searchInput: Math.round(input?.height ?? -1),
      toolbarH: Math.round(toolbar?.height ?? -1),
      overflow: document.documentElement.scrollWidth - window.innerWidth,
    };
  })()`);
  console.log(`${w}x${h}`, JSON.stringify(m));
}
chrome.kill();

